package study

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"
)

const legacyRunStateGCThreshold = 64 * 1024 * 1024

var (
	ErrRunStateMissing     = errors.New("run state missing")
	ErrRunStateMalformed   = errors.New("run state malformed")
	ErrRunStateUnsupported = errors.New("run state unsupported")
)

type atomicWriteHooks struct {
	BeforeRename func(path string) error
}

func LoadRunState(study Study) (RunState, error) {
	if state, found, err := loadRunStateDatabase(study); err != nil {
		return RunState{}, err
	} else if found {
		if err := ValidateRunState(state, RunStatePath(study)); err != nil {
			return RunState{}, err
		}
		return state, nil
	}
	path := RunStatePath(study)
	content, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return RunState{}, fmt.Errorf("%w: %s", ErrRunStateMissing, path)
		}
		return RunState{}, fmt.Errorf("read run state %s: %w", path, err)
	}
	var state RunState
	if err := json.Unmarshal(content, &state); err != nil {
		return RunState{}, fmt.Errorf("%w: %s: %w", ErrRunStateMalformed, path, err)
	}
	if err := ValidateRunState(state, path); err != nil {
		return RunState{}, err
	}
	compactRunStateDiagnostics(&state)
	if len(content) >= legacyRunStateGCThreshold {
		content = nil
		runtime.GC()
	}
	return state, nil
}

func SaveRunState(study Study, state RunState) error {
	if authoritative, err := RunStateInDatabase(study); err != nil {
		return err
	} else if authoritative {
		if err := saveRunStateDatabase(study, state); err != nil {
			return err
		}
		if !state.Complete {
			return nil
		}
	}
	return saveRunStateWithHooks(study, state, atomicWriteHooks{})
}

func saveRunStateWithHooks(study Study, state RunState, hooks atomicWriteHooks) error {
	path := RunStatePath(study)
	state = cloneRunState(state)
	state.UpdatedAt = time.Now().UTC()
	compactRunStateDiagnostics(&state)
	if err := ValidateRunState(state, path); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create run state directory %s: %w", filepath.Dir(path), err)
	}
	temp, err := os.CreateTemp(filepath.Dir(path), "."+RunStateFileName+".*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary run state %s: %w", path, err)
	}
	tempPath := temp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tempPath)
		}
	}()
	encoder := json.NewEncoder(temp)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(state); err != nil {
		_ = temp.Close()
		return fmt.Errorf("encode temporary run state %s: %w", tempPath, err)
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return fmt.Errorf("flush temporary run state %s: %w", tempPath, err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("close temporary run state %s: %w", tempPath, err)
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(path); err != nil {
			return fmt.Errorf("prepare run state rename %s: %w", path, err)
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return fmt.Errorf("rename run state %s: %w", path, err)
	}
	cleanup = false
	syncDir(filepath.Dir(path))
	return nil
}

func ValidateRunState(state RunState, path string) error {
	if state.SchemaVersion == 0 {
		return fmt.Errorf("%w: %s: missing schema_version", ErrRunStateMalformed, path)
	}
	if state.SchemaVersion != RunStateSchemaVersion {
		return fmt.Errorf("%w: %s: schema_version %d", ErrRunStateUnsupported, path, state.SchemaVersion)
	}
	if state.RunID == "" {
		return fmt.Errorf("%w: %s: missing run_id", ErrRunStateMalformed, path)
	}
	if state.Study == "" {
		return fmt.Errorf("%w: %s: missing study", ErrRunStateMalformed, path)
	}
	if state.CreatedAt.IsZero() || state.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: %s: missing timestamps", ErrRunStateMalformed, path)
	}
	ids := map[string]struct{}{}
	for i, task := range state.Tasks {
		if task.ID == "" {
			return fmt.Errorf("%w: %s: task %d missing id", ErrRunStateMalformed, path, i)
		}
		if _, exists := ids[task.ID]; exists {
			return fmt.Errorf("%w: %s: duplicate task id %q", ErrRunStateMalformed, path, task.ID)
		}
		ids[task.ID] = struct{}{}
		if task.Kind != TaskKindAnalysis && task.Kind != TaskKindSynthesis {
			return fmt.Errorf("%w: %s: task %q has unsupported kind %q", ErrRunStateMalformed, path, task.ID, task.Kind)
		}
		if !validTaskStatus(task.Status) {
			return fmt.Errorf("%w: %s: task %q has unsupported status %q", ErrRunStateMalformed, path, task.ID, task.Status)
		}
		if task.Study == "" || task.OutputPath == "" || task.CreatedAt.IsZero() || task.UpdatedAt.IsZero() {
			return fmt.Errorf("%w: %s: task %q missing required fields", ErrRunStateMalformed, path, task.ID)
		}
		if task.Kind == TaskKindAnalysis && (task.Dimension == "" || task.Source == "" || task.SourceKind == "") {
			return fmt.Errorf("%w: %s: analysis task %q missing metadata", ErrRunStateMalformed, path, task.ID)
		}
		if task.Session != nil {
			session := task.Session
			if session.SessionID == "" || session.WorkDir == "" || session.InputFingerprint == "" || session.UpdatedAt.IsZero() || session.ContinueFailures < 0 || len(session.SessionID) > 512 || strings.ContainsAny(session.SessionID, "\x00\r\n") {
				return fmt.Errorf("%w: %s: task %q has invalid session checkpoint", ErrRunStateMalformed, path, task.ID)
			}
		}
	}
	return nil
}

func validTaskStatus(status TaskStatus) bool {
	switch status {
	case TaskStatusPending, TaskStatusRunning, TaskStatusValidating, TaskStatusCompleted, TaskStatusFailed, TaskStatusCancelled, TaskStatusSkipped, TaskStatusWaiting, TaskStatusRetrying:
		return true
	default:
		return false
	}
}

func syncDir(path string) {
	dir, err := os.Open(path)
	if err != nil {
		return
	}
	defer dir.Close()
	_ = dir.Sync()
}

package study

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type NewRunStateRequest struct {
	WorkspaceRoot string
	Study         Study
	Sources       []Source
	Dimensions    []Dimension
	RunID         string
	Now           time.Time
	Filters       RunFilters
	Config        ConfigSummary
}

func NewRunState(req NewRunStateRequest) (RunState, error) {
	now := req.Now
	if now.IsZero() {
		now = time.Now().UTC()
	}
	runID := strings.TrimSpace(req.RunID)
	if runID == "" {
		runID = fmt.Sprintf("run-%s", now.UTC().Format("20060102T150405Z"))
	}

	dimensions := append([]Dimension(nil), req.Dimensions...)
	sort.Slice(dimensions, func(i, j int) bool {
		if dimensions[i].Number == dimensions[j].Number {
			return dimensions[i].Slug < dimensions[j].Slug
		}
		return dimensions[i].Number < dimensions[j].Number
	})

	sources := append([]Source(nil), req.Sources...)
	sort.Slice(sources, func(i, j int) bool {
		if sources[i].Name == sources[j].Name {
			return sources[i].Kind < sources[j].Kind
		}
		return sources[i].Name < sources[j].Name
	})

	tasks, fingerprint := buildCurrentTaskGraph(req.WorkspaceRoot, req.Study, sources, dimensions, now)
	return RunState{
		SchemaVersion:            RunStateSchemaVersion,
		RunID:                    runID,
		Study:                    req.Study.Name,
		CreatedAt:                now,
		UpdatedAt:                now,
		Filters:                  req.Filters,
		Config:                   req.Config,
		ApplicabilityFingerprint: fingerprint,
		Tasks:                    tasks,
		Complete:                 len(tasks) == 0,
	}, nil
}

func ReconcileRunState(state *RunState, workspaceRoot string, study Study, sources []Source, dimensions []Dimension, now time.Time) {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	current, fingerprint := buildCurrentTaskGraph(workspaceRoot, study, sources, dimensions, now)
	existing := make(map[string]TaskState, len(state.Tasks))
	for _, task := range state.Tasks {
		existing[task.ID] = task
	}
	for i := range current {
		if prior, ok := existing[current[i].ID]; ok {
			expected := current[i]
			current[i] = prior
			current[i].Dimension = expected.Dimension
			current[i].DimensionRef = expected.DimensionRef
			current[i].Source = expected.Source
			current[i].SourceKind = expected.SourceKind
			current[i].OutputPath = expected.OutputPath
			current[i].Dependencies = expected.Dependencies
			if current[i].Kind == TaskKindSynthesis && dependenciesChanged(prior.Dependencies, current[i].Dependencies) && prior.Status == TaskStatusCompleted {
				current[i].Status = TaskStatusPending
				current[i].CompletedAt = nil
				current[i].Validation = nil
				current[i].LastError = nil
				current[i].UpdatedAt = now
			}
		}
	}
	sort.Slice(current, func(i, j int) bool { return current[i].ID < current[j].ID })
	state.Tasks = current
	state.ApplicabilityFingerprint = fingerprint
	state.UpdatedAt = now
	state.Complete = allTasksComplete(*state)
}

func buildCurrentTaskGraph(workspaceRoot string, study Study, sources []Source, dimensions []Dimension, now time.Time) ([]TaskState, string) {
	dimensions = append([]Dimension(nil), dimensions...)
	sort.Slice(dimensions, func(i, j int) bool {
		if dimensions[i].Number == dimensions[j].Number {
			return dimensions[i].Slug < dimensions[j].Slug
		}
		return dimensions[i].Number < dimensions[j].Number
	})
	sources = append([]Source(nil), sources...)
	sort.Slice(sources, func(i, j int) bool {
		if sources[i].Name == sources[j].Name {
			return sources[i].Kind < sources[j].Kind
		}
		return sources[i].Name < sources[j].Name
	})
	var tasks []TaskState
	var fingerprint strings.Builder
	for _, dimension := range dimensions {
		fmt.Fprintf(&fingerprint, "dimension:%s:%s\n", dimension.Number, dimension.Slug)
		applicable := GetApplicableSources(sources, dimension)
		sort.Slice(applicable, func(i, j int) bool {
			if applicable[i].Name == applicable[j].Name {
				return applicable[i].Kind < applicable[j].Kind
			}
			return applicable[i].Name < applicable[j].Name
		})
		if len(applicable) == 0 {
			continue
		}
		var deps []SynthesisDependency
		for _, source := range applicable {
			fmt.Fprintf(&fingerprint, "source:%s:%s:%s\n", dimension.Number, source.Name, source.Kind)
			id := analysisTaskID(study, dimension, source)
			outputPath := relPath(workspaceRoot, SourceReportPath(study, source, dimension))
			tasks = append(tasks, TaskState{
				ID:           id,
				Kind:         TaskKindAnalysis,
				Status:       TaskStatusPending,
				Study:        study.Name,
				Dimension:    dimension.Number,
				DimensionRef: dimension.Ref(),
				Source:       source.Name,
				SourceKind:   source.Kind,
				OutputPath:   outputPath,
				CreatedAt:    now,
				UpdatedAt:    now,
			})
			deps = append(deps, SynthesisDependency{
				TaskID:     id,
				Source:     source.Name,
				SourceKind: source.Kind,
				ReportPath: outputPath,
			})
		}
		sort.Slice(deps, func(i, j int) bool { return deps[i].TaskID < deps[j].TaskID })
		tasks = append(tasks, TaskState{
			ID:           synthesisTaskID(study, dimension),
			Kind:         TaskKindSynthesis,
			Status:       TaskStatusPending,
			Study:        study.Name,
			Dimension:    dimension.Number,
			DimensionRef: dimension.Ref(),
			OutputPath:   relPath(workspaceRoot, FinalReportPath(study, dimension)),
			CreatedAt:    now,
			UpdatedAt:    now,
			Dependencies: deps,
		})
	}

	sort.Slice(tasks, func(i, j int) bool { return tasks[i].ID < tasks[j].ID })
	sum := sha256.Sum256([]byte(fingerprint.String()))
	return tasks, "sha256:" + hex.EncodeToString(sum[:])
}

func dependenciesChanged(a, b []SynthesisDependency) bool {
	if len(a) != len(b) {
		return true
	}
	for i := range a {
		if a[i] != b[i] {
			return true
		}
	}
	return false
}

func RunStatePath(study Study) string {
	return filepath.Join(study.Path, RunStateDirName, RunStateFileName)
}

func SummarizeRunState(state RunState, statePath string) StatusSummary {
	summary := SummarizeRunStateCounts(state, statePath)
	summary.Tasks = append([]TaskState(nil), state.Tasks...)
	return summary
}

// SummarizeRetries aggregates retry activity across tasks. A retry continued
// the same agent session when a compatible durable checkpoint exists without
// recorded continue failures; otherwise the retry started a fresh session.
func SummarizeRetries(state RunState) RetrySummary {
	var summary RetrySummary
	for _, task := range state.Tasks {
		retries := task.Attempts - 1
		if retries < 0 {
			retries = 0
		}
		if retries > 0 {
			summary.RetriedTasks++
			summary.TotalRetries += retries
			if TaskSessionContinued(task) {
				summary.SameSession++
			} else {
				summary.FreshSession++
			}
		}
		if task.Status == TaskStatusRetrying {
			summary.Waiting++
		}
		if task.RetryAfter != nil && (summary.NextRetryAt == nil || task.RetryAfter.Before(*summary.NextRetryAt)) {
			next := *task.RetryAfter
			summary.NextRetryAt = &next
		}
	}
	return summary
}

// TaskSessionContinued reports whether a task's retries continued the same
// agent session: a durable checkpoint exists without recorded continue
// failures.
func TaskSessionContinued(task TaskState) bool {
	return task.Session != nil && task.Session.SessionID != "" && task.Session.ContinueFailures == 0
}

func SummarizeRunStateCounts(state RunState, statePath string) StatusSummary {
	summary := StatusSummary{Total: len(state.Tasks), Complete: state.Complete, StatePath: statePath, RunID: state.RunID}
	for _, task := range state.Tasks {
		countTaskStatus(&summary, task)
	}
	return summary
}

func countTaskStatus(summary *StatusSummary, task TaskState) {
	switch task.Status {
	case TaskStatusPending:
		summary.Pending++
	case TaskStatusRunning:
		summary.Running++
		summary.Active++
	case TaskStatusValidating:
		summary.Validating++
		summary.Active++
	case TaskStatusCompleted:
		summary.Completed++
	case TaskStatusFailed:
		summary.Failed++
	case TaskStatusCancelled:
		summary.Cancelled++
	case TaskStatusSkipped:
		summary.Skipped++
	case TaskStatusWaiting:
		summary.Waiting++
		summary.Active++
	case TaskStatusRetrying:
		summary.Retrying++
		summary.Active++
	}
	if task.RetryAfter != nil {
		summary.RetryCount++
		if summary.NextRetryAt == nil || task.RetryAfter.Before(*summary.NextRetryAt) {
			next := *task.RetryAfter
			summary.NextRetryAt = &next
		}
	}
}

func ResumeValidateRunState(state *RunState, study Study, sources []Source, dimensions []Dimension, now time.Time) {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	sourceByKey := map[string]Source{}
	for _, source := range sources {
		sourceByKey[sourceKey(source.Name, source.Kind)] = source
	}
	dimensionByRef := map[string]Dimension{}
	for _, dimension := range dimensions {
		dimensionByRef[dimension.Ref()] = dimension
		dimensionByRef[dimension.Number] = dimension
	}
	for i := range state.Tasks {
		task := &state.Tasks[i]
		switch task.Status {
		case TaskStatusRunning, TaskStatusValidating, TaskStatusWaiting, TaskStatusCancelled:
			task.Status = TaskStatusPending
			task.RetryAfter = nil
			task.UpdatedAt = now
		case TaskStatusRetrying:
			if task.RetryAfter == nil || !task.RetryAfter.After(now) {
				task.Status = TaskStatusPending
				task.RetryAfter = nil
				task.UpdatedAt = now
			}
		case TaskStatusFailed:
			if task.RetryAfter != nil {
				if task.RetryAfter.After(now) {
					task.Status = TaskStatusRetrying
				} else {
					task.Status = TaskStatusPending
					task.RetryAfter = nil
				}
				task.UpdatedAt = now
			}
		case TaskStatusCompleted:
			var result ValidationResult
			switch task.Kind {
			case TaskKindAnalysis:
				source, sourceOK := sourceByKey[sourceKey(task.Source, task.SourceKind)]
				dimension, dimensionOK := dimensionByRef[task.DimensionRef]
				if !dimensionOK {
					dimension, dimensionOK = dimensionByRef[task.Dimension]
				}
				if !sourceOK || !dimensionOK {
					task.Status = TaskStatusFailed
					task.LastError = &TaskError{Code: "validation.reference", Message: "completed task references unknown source or dimension"}
					task.UpdatedAt = now
					continue
				}
				result = ValidateSourceReport(study, source, dimension)
			case TaskKindSynthesis:
				dimension, dimensionOK := dimensionByRef[task.DimensionRef]
				if !dimensionOK {
					dimension, dimensionOK = dimensionByRef[task.Dimension]
				}
				if !dimensionOK {
					task.Status = TaskStatusFailed
					task.LastError = &TaskError{Code: "validation.reference", Message: "completed task references unknown dimension"}
					task.UpdatedAt = now
					continue
				}
				result = ValidateFinalReport(study, dimension)
			default:
				continue
			}
			summary := validationSummary(result, now)
			task.Validation = &summary
			if result.Status != ValidationStatusPassed {
				task.Status = TaskStatusFailed
				task.LastError = &TaskError{Code: "validation.report", Message: summary.Message, Path: summary.Path}
			}
			task.UpdatedAt = now
		}
	}
	state.Complete = true
	for _, task := range state.Tasks {
		if task.Status != TaskStatusCompleted && task.Status != TaskStatusSkipped {
			state.Complete = false
			break
		}
	}
	state.UpdatedAt = now
}

// RestoreCompletedRunHistory recovers tasks that reconciliation reopened after
// a transient graph change when their last completed artifact is still valid.
// A history record is required, so arbitrary stale files are never adopted.
func RestoreCompletedRunHistory(state *RunState, study Study, sources []Source, dimensions []Dimension, records []RunHistoryRecord, now time.Time) {
	completed := map[string]RunHistoryRecord{}
	for _, record := range records {
		if record.Status == TaskStatusCompleted && record.ValidationStatus == ValidationStatusPassed {
			completed[record.TaskID] = record
		}
	}
	sourceByKey := map[string]Source{}
	for _, source := range sources {
		sourceByKey[sourceKey(source.Name, source.Kind)] = source
	}
	dimensionByRef := map[string]Dimension{}
	for _, dimension := range dimensions {
		dimensionByRef[dimension.Ref()] = dimension
		dimensionByRef[dimension.Number] = dimension
	}
	restoreKind := func(kind TaskKind) {
		for i := range state.Tasks {
			task := &state.Tasks[i]
			record, ok := completed[task.ID]
			if !ok || task.Status != TaskStatusPending || task.Kind != kind {
				continue
			}
			if kind == TaskKindSynthesis && !dependenciesComplete(*state, *task) {
				continue
			}
			var validation ValidationResult
			dimension, dimensionOK := dimensionByRef[task.DimensionRef]
			if !dimensionOK {
				dimension, dimensionOK = dimensionByRef[task.Dimension]
			}
			if !dimensionOK {
				continue
			}
			if kind == TaskKindAnalysis {
				source, sourceOK := sourceByKey[sourceKey(task.Source, task.SourceKind)]
				if !sourceOK {
					continue
				}
				validation = ValidateSourceReport(study, source, dimension)
			} else {
				validation = ValidateFinalReport(study, dimension)
			}
			if validation.Status != ValidationStatusPassed {
				continue
			}
			task.Status = TaskStatusCompleted
			summary := validationSummary(validation, now)
			task.Validation = &summary
			task.LastError = nil
			task.RetryAfter = nil
			task.UpdatedAt = now
			if record.CompletedAt != nil {
				completedAt := *record.CompletedAt
				task.CompletedAt = &completedAt
			} else {
				completedAt := now
				task.CompletedAt = &completedAt
			}
		}
	}
	restoreKind(TaskKindAnalysis)
	restoreKind(TaskKindSynthesis)
}

func validationSummary(result ValidationResult, now time.Time) ValidationSummary {
	summary := ValidationSummary{Status: result.Status, CheckedAt: now, Path: result.Path}
	for _, check := range result.Checks {
		switch check.Status {
		case ValidationStatusPassed:
			summary.PassedChecks++
		case ValidationStatusFailed:
			summary.FailedChecks++
		}
	}
	if result.Err != nil {
		summary.Message = result.Err.Error()
	}
	return summary
}

func analysisTaskID(study Study, dimension Dimension, source Source) string {
	return strings.Join([]string{
		string(TaskKindAnalysis),
		slugID(study.Name),
		dimension.Number,
		slugID(dimension.Slug),
		slugID(source.Name),
		string(source.Kind),
	}, ":")
}

func synthesisTaskID(study Study, dimension Dimension) string {
	return strings.Join([]string{string(TaskKindSynthesis), slugID(study.Name), dimension.Number, slugID(dimension.Slug)}, ":")
}

func slugID(value string) string {
	value = normalizeSlug(value)
	if value == "" {
		return "none"
	}
	return value
}

func relPath(root, path string) string {
	if root == "" {
		return filepath.ToSlash(filepath.Clean(path))
	}
	return workspace.Rel(root, path)
}

func sourceKey(name string, kind SourceKind) string {
	return name + "\x00" + string(kind)
}

package study

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

var ErrStudyLocked = errors.New("study run-loop locked")

var processAlive = func(pid int) bool {
	if pid <= 0 {
		return false
	}
	err := syscall.Kill(pid, 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

func RunLoopLockPath(study Study) string {
	return filepath.Join(study.Path, RunStateDirName, "run-loop.lock")
}

type studyLock struct {
	path string
	info LockInfo
}

func AcquireRunLoopLock(study Study, command []string, force bool, now time.Time) (*studyLock, error) {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	path := RunLoopLockPath(study)
	if force {
		if err := ForceUnlockRunLoop(study); err != nil {
			return nil, err
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, fmt.Errorf("create lock directory %s: %w", filepath.Dir(path), err)
	}
	info := LockInfo{
		Path:       path,
		Study:      study.Name,
		PID:        os.Getpid(),
		Command:    sanitizeCommand(command),
		AcquiredAt: now.UTC(),
	}
	content, err := json.MarshalIndent(info, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal lock %s: %w", path, err)
	}
	content = append(content, '\n')
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		if errors.Is(err, fs.ErrExist) {
			existing, readErr := ReadRunLoopLock(study)
			if readErr != nil {
				return nil, fmt.Errorf("%w: %s exists and could not be read: %v", ErrStudyLocked, path, readErr)
			}
			if !processAlive(existing.PID) {
				if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
					return nil, fmt.Errorf("%w: stale lock %s held by dead pid %d could not be removed: %v", ErrStudyLocked, path, existing.PID, err)
				}
				file, err = os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
				if err == nil {
					goto writeLock
				}
				if errors.Is(err, fs.ErrExist) {
					replaced, readErr := ReadRunLoopLock(study)
					if readErr != nil {
						return nil, fmt.Errorf("%w: %s exists and could not be read after stale cleanup: %v", ErrStudyLocked, path, readErr)
					}
					return nil, fmt.Errorf("%w: %s held by pid %d since %s command %q", ErrStudyLocked, path, replaced.PID, replaced.AcquiredAt.Format(time.RFC3339), replaced.Command)
				}
				return nil, fmt.Errorf("create lock %s after stale cleanup: %w", path, err)
			}
			return nil, fmt.Errorf("%w: %s held by pid %d since %s command %q", ErrStudyLocked, path, existing.PID, existing.AcquiredAt.Format(time.RFC3339), existing.Command)
		}
		return nil, fmt.Errorf("create lock %s: %w", path, err)
	}
writeLock:
	if _, err := file.Write(content); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return nil, fmt.Errorf("write lock %s: %w", path, err)
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return nil, fmt.Errorf("flush lock %s: %w", path, err)
	}
	if err := file.Close(); err != nil {
		_ = os.Remove(path)
		return nil, fmt.Errorf("close lock %s: %w", path, err)
	}
	return &studyLock{path: path, info: info}, nil
}

func (l *studyLock) Release() error {
	if l == nil {
		return nil
	}
	info, err := readLockPath(l.path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return err
	}
	if info.PID != l.info.PID || info.Study != l.info.Study || !info.AcquiredAt.Equal(l.info.AcquiredAt) {
		return fmt.Errorf("lock %s ownership changed; refusing release", l.path)
	}
	if err := os.Remove(l.path); err != nil {
		return fmt.Errorf("release lock %s: %w", l.path, err)
	}
	return nil
}

func ReadRunLoopLock(study Study) (LockInfo, error) {
	return readLockPath(RunLoopLockPath(study))
}

// RunLoopActive reports whether the study lock belongs to a live process.
// A missing, malformed, or stale lock is not presented as an active run.
func RunLoopActive(study Study) (bool, LockInfo, error) {
	info, err := ReadRunLoopLock(study)
	if err != nil {
		return false, LockInfo{}, err
	}
	return processAlive(info.PID), info, nil
}

// CancelRunLoop asks the live lock owner to cancel gracefully. The owner
// persists terminal state and releases the lock through its normal context path.
func CancelRunLoop(study Study) (LockInfo, error) {
	active, info, err := RunLoopActive(study)
	if err != nil {
		return LockInfo{}, fmt.Errorf("inspect run-loop lock: %w", err)
	}
	if !active {
		return info, fmt.Errorf("study run-loop is not active")
	}
	if info.Study != "" && info.Study != study.Name {
		return info, fmt.Errorf("run-loop lock belongs to study %q", info.Study)
	}
	if info.PID == os.Getpid() {
		return info, fmt.Errorf("cannot signal the current process; use its operation context")
	}
	if err := syscall.Kill(info.PID, syscall.SIGINT); err != nil {
		return info, fmt.Errorf("request run-loop cancellation from pid %d: %w", info.PID, err)
	}
	return info, nil
}

func ForceUnlockRunLoop(study Study) error {
	path := RunLoopLockPath(study)
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("force unlock %s: %w", path, err)
	}
	return nil
}

func readLockPath(path string) (LockInfo, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return LockInfo{}, err
	}
	var info LockInfo
	if err := json.Unmarshal(content, &info); err != nil {
		return LockInfo{}, fmt.Errorf("parse lock %s: %w", path, err)
	}
	if info.Path == "" {
		info.Path = path
	}
	return info, nil
}

func sanitizeCommand(args []string) string {
	if len(args) == 0 {
		return "ultraplan study run-loop"
	}
	safe := make([]string, 0, len(args))
	for _, arg := range args {
		lower := strings.ToLower(arg)
		if strings.Contains(lower, "token") || strings.Contains(lower, "key") || strings.Contains(lower, "secret") {
			safe = append(safe, "[redacted]")
			continue
		}
		if len(arg) > 120 {
			safe = append(safe, arg[:120]+"...")
			continue
		}
		safe = append(safe, arg)
	}
	return strings.Join(safe, " ")
}

