package study

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

// Reproduction: mid-flight cancellation (SIGINT-equivalent) must drain workers,
// persist their terminal states via the final forced save, and surface the
// cancellation convention. Instead, debounced persists race the cancelled
// context, firstErr becomes context.Canceled, RunLoop early-returns BEFORE the
// final forced save/SyncRunHistory, losing terminal task states.
type gauntletCancelRuntime struct {
	mu       sync.Mutex
	started  chan struct{}
	sessions int
}

func (r *gauntletCancelRuntime) StartRun(ctx context.Context, req runtimepkg.Request) (runtimepkg.Result, error) {
	r.mu.Lock()
	r.sessions++
	r.mu.Unlock()
	select {
	case r.started <- struct{}{}:
	case <-ctx.Done():
	}
	<-ctx.Done()
	return runtimepkg.Result{Status: "cancelled", Error: &runtimepkg.Error{Category: "cancellation"}}, ctx.Err()
}

func TestGauntletMidFlightCancelPersistsTerminalStates(t *testing.T) {
	previousDiskReader := readSchedulerDiskPressure
	readSchedulerDiskPressure = func(string) diskPressure {
		return diskPressure{TotalBytes: 100 << 30, AvailableBytes: 50 << 30}
	}
	t.Cleanup(func() { readSchedulerDiskPressure = previousDiskReader })
	root, st := executionFixture(t)
	mkdir(t, root, "studies", "demo", "sources", "second")
	rt := &gauntletCancelRuntime{started: make(chan struct{}, 8)}
	service := NewService(root, WithRuntime(rt, runtimeRequest()))
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	done := make(chan struct{})
	var runErr error
	go func() {
		defer close(done)
		_, runErr = service.RunLoop(ctx, RunLoopRequest{
			StudyRef: "demo", Parallelism: 2,
			Command: []string{"ultraplan", "study", "demo", "run-loop"},
		})
	}()
	for i := 0; i < 2; i++ {
		select {
		case <-rt.started:
		case <-time.After(10 * time.Second):
			t.Fatal("two workers did not start")
		}
	}
	cancel()
	select {
	case <-done:
	case <-time.After(15 * time.Second):
		t.Fatal("RunLoop did not return")
	}

	if runErr == nil || !errors.Is(runErr, context.Canceled) {
		t.Fatalf("RunLoop err = %v, want context.Canceled (early return path)", runErr)
	}
	loaded, err := LoadRunState(st)
	if err != nil {
		t.Fatal(err)
	}
	stuck := 0
	for _, task := range loaded.Tasks {
		if task.Kind == TaskKindAnalysis && task.Status == TaskStatusRunning {
			stuck++
			t.Logf("task %s left status=%q in durable state (worker returned cancelled)", task.ID, task.Status)
		}
	}
	if stuck == 0 {
		t.Log("NOTE: no stuck running tasks this run (persists did not collide); timing-dependent")
	}
	records, err := LoadRunHistory(st)
	if err != nil {
		t.Fatal(err)
	}
	cancelled := 0
	for _, rec := range records {
		if rec.Status == TaskStatusCancelled {
			cancelled++
		}
	}
	t.Logf("durable-state running-analysis=%d history-cancelled-records=%d", stuck, cancelled)
	if stuck > 0 && cancelled == 0 {
		t.Fatalf("state lost terminal statuses and history has none either")
	}
	if stuck > 0 && cancelled > 0 {
		t.Fatalf("DEFECT CONFIRMED: %d task(s) still 'running' in canonical state while history ledger holds %d cancelled record(s); RunLoop returned %v and skipped the final forced save", stuck, cancelled, runErr)
	}
	if stuck == 0 {
		t.Skip("timing did not reproduce collision")
	}
}
EOF
